/**
 * iOS App Data Cleaner
 * Recreates Android "adb shell pm clear" functionality for iOS.
 *
 * Usage (via Frida REPL):
 *   frida -U SpringBoard -l clearAppData.js
 *   > clearAppAll('com.example.app')
 *
 * Methods:
 *   clearAppData(bundleID: string) -> {success: boolean, error?: string}
 *     - Clears app data directories only (Library, Documents, Caches, Tmp)
 *
 *   clearAppPermissions(bundleID: string) -> {success: boolean, error?: string}
 *     - Resets app permissions (TCC, Location) only
 *
 *   clearAppKeyChain(bundleID: string) -> {success: boolean, error?: string}
 *     - Clears app keychain entries only
 *
 *   clearAppAll(bundleID: string) -> {success: boolean, error?: string}
 *     - Performs complete reset: data + permissions + keychain
 *
 * Author: github.com/lorenzodifuccia
 * Inspired by: github.com/FouadRaheb/AppData and github.com/sensepost/objection
 */


// List of protected system bundle IDs that cannot be cleared
const PROTECTED_BUNDLE_IDS = [
    'in.palera.loader',
    'science.xnu.undecimus',
    'com.odysseyteam.odyssey',
    'org.coolstar.SileoStore',
    'com.saurik.Cydia',
    'com.opa334.TrollStore',
    'com.opa334.trollstorepersistencehelper',
];

// Get LSApplicationProxy for bundle ID
function getApplicationProxy(bundleID) {
    const LSApplicationProxy = ObjC.classes.LSApplicationProxy;
    if (!LSApplicationProxy) {
        throw new Error('LSApplicationProxy not available');
    }

    const proxy = LSApplicationProxy.applicationProxyForIdentifier_(bundleID);

    if (!proxy || proxy.handle.isNull()) {
        throw new Error(`App not found: ${bundleID}`);
    }

    return proxy;
}

// Get app container paths
function getAppPaths(bundleID) {
    const proxy = getApplicationProxy(bundleID);
    const dataContainerURL = proxy.dataContainerURL();

    if (!dataContainerURL || dataContainerURL.handle.isNull()) {
        throw new Error('Could not get data container URL');
    }

    const dataContainer = dataContainerURL.path().toString();
    const bundleURL = proxy.bundleURL();

    return {
        dataContainer,
        bundleContainer: bundleURL ? bundleURL.path().toString() : null,
        library: `${dataContainer}/Library`,
        documents: `${dataContainer}/Documents`,
        caches: `${dataContainer}/Library/Caches`,
        tmp: `${dataContainer}/tmp`,
        preferences: `${dataContainer}/Library/Preferences`
    };
}

// Terminate app
function terminateApp(bundleID) {
    try {
        // Method 1: SBSApplicationTerminationAssertion
        const SBSCreateFn = Process.findModuleByName('SpringBoardServices')
            ?.findExportByName('SBSApplicationTerminationAssertionCreateWithError');

        if (SBSCreateFn) {
            const assertion = new NativeFunction(SBSCreateFn, 'pointer', ['pointer', 'pointer', 'int', 'pointer'])
                (NULL, bundleID.handle, 1, NULL);

            if (assertion && !assertion.isNull()) {
                const SBSInvalidateFn = Process.findModuleByName('SpringBoardServices')
                    ?.findExportByName('SBSApplicationTerminationAssertionInvalidate');

                if (SBSInvalidateFn) {
                    new NativeFunction(SBSInvalidateFn, 'void', ['pointer'])(assertion);
                }
                return;
            }
        }

        // Method 2: FBSSystemService
        const FBSSystemService = ObjC.classes.FBSSystemService;
        if (FBSSystemService) {
            FBSSystemService.sharedService().terminateApplicationGroup_forReason_andReport_withDescription_(
                bundleID, 5, false, ObjC.classes.NSString.stringWithString_('App data reset')
            );
            return;
        }

        // Method 3: BKSTerminateApplicationForReasonAndReportWithDescription
        const BKSTerminateFn = Process.findModuleByName('BackBoardServices')
            ?.findExportByName('BKSTerminateApplicationForReasonAndReportWithDescription');

        if (BKSTerminateFn) {
            new NativeFunction(BKSTerminateFn, 'void', ['pointer', 'int', 'int', 'pointer'])
                (bundleID.handle, 5, 0, ObjC.classes.NSString.stringWithString_('App data reset').handle);
        }
    } catch (e) {
        console.error(`App termination failed: ${e.message}`);
    }
}

// Clear all app data directories
function clearAppDataDirectories(paths) {
    const fileManager = ObjC.classes.NSFileManager.defaultManager();
    const NSString = ObjC.classes.NSString;
    const error = Memory.alloc(Process.pointerSize);

    [paths.library, paths.documents, paths.caches, paths.tmp].forEach(dirPath => {
        const dirPathStr = NSString.stringWithString_(dirPath);
        if (!fileManager.fileExistsAtPath_(dirPathStr)) return;

        error.writePointer(NULL);
        const contents = fileManager.contentsOfDirectoryAtPath_error_(dirPathStr, error);
        if (!contents) return;

        for (let i = 0; i < contents.count(); i++) {
            error.writePointer(NULL);
            fileManager.removeItemAtPath_error_(
                NSString.stringWithString_(`${dirPath}/${contents.objectAtIndex_(i)}`), error
            );
        }
    });

    // Recreate empty Preferences directory
    error.writePointer(NULL);
    fileManager.createDirectoryAtPath_withIntermediateDirectories_attributes_error_(
        NSString.stringWithString_(paths.preferences), true, NULL, error
    );
}

// Clear Keychain (based on `objection` implementation)
function clearKeychain(bundleID) {
    try {
        const SecItemDelete = new NativeFunction(
            Process.findModuleByName('Security').findExportByName('SecItemDelete'),
            'int', ['pointer']
        );

        const itemClasses = [
            "keys", // kSecClassKey
            "idnt", // kSecClassIdentity
            "cert", // kSecClassCertificate
            "genp", // kSecClassGenericPassword
            "inet"  // kSecClassInternetPassword
        ];

        // Clear by service attribute and access group
        [["svce", bundleID], ["agrp", bundleID]].forEach(([key, value]) => {
            const searchDict = ObjC.classes.NSMutableDictionary.alloc().init();
            searchDict.setObject_forKey_("syna", "sync");
            searchDict.setObject_forKey_(value, key);

            itemClasses.forEach(cls => {
                searchDict.setObject_forKey_(cls, "class");
                SecItemDelete(searchDict.handle);
            });
        });
    } catch (e) {
        console.error(`Keychain clearing failed: ${e.message}`);
