// Helper function to execute clear operations
function executeClear(bundleID, operation) {
    try {
        // Platform check
        if (!ObjC.available) {
            if (Java.available) {
                console.log(`[!] Running on Android - Use native command instead:`);
                console.log(`    adb shell pm clear ${bundleID}`);
                throw new Error(`Use adb shell pm clear ${bundleID} on Android`);
            }
            throw new Error('ObjC runtime not available - This script requires iOS');
        }

        if (!bundleID || typeof bundleID !== 'string') {
            throw new Error('Invalid bundle ID');
        }

        if (bundleID.startsWith('com.apple.') || PROTECTED_BUNDLE_IDS.includes(bundleID)) {
            throw new Error(`Blocked reset for app: ${bundleID}`);
        }

        const bundleIDNS = ObjC.classes.NSString.stringWithString_(bundleID);
        const paths = getAppPaths(bundleIDNS);
        terminateApp(bundleIDNS);
        operation(bundleIDNS, paths);

        return { success: true };
    } catch (e) {
        console.error(`Error: ${e.message}`, e.stack);
        return { success: false, error: e.message };
    }
}

